import { useEffect, useState } from 'react';

/**
 * How much room the app has, in four steps, after Material 3's window size
 * classes (compact under 600, medium 600–839, expanded 840 and up, large
 * 1200 and up).
 *
 * - `compact` is a phone, and also anything short: a phone on its side is
 *   600 or more wide but under 480 tall, and it keeps the phone layout, the
 *   bottom bar and the bottom sheets. Nothing about a phone changes here.
 * - `medium` is a tablet held upright or a small window: a navigation rail
 *   replaces the bottom bar, sheets become centred dialogs, and the column
 *   gets a little wider.
 * - `expanded` has room for two panes: the notebook beside the word you
 *   picked, Settings beside the page it opens, Progress as a grid of cards.
 *   It starts at 1024 rather than Material's 840 because the list pane is a
 *   phone's width and the rail takes some of what is left; at 840 the word
 *   would be squeezed into four hundred pixels.
 * - `large` is a laptop or a desktop window: the rail opens into a sidebar
 *   with the labels beside the icons, and Today lays out in two columns.
 *
 * The same numbers are written into the stylesheets as media queries, since
 * CSS cannot read them from here; `windowClass.test.ts` fails if a
 * stylesheet uses a width step that is not one of these.
 */
export type WindowClass = 'compact' | 'medium' | 'expanded' | 'large';

/** Shorter than this is a phone on its side, whatever its width. */
export const MIN_TALL_HEIGHT = 480;

/** Where each class starts, in CSS pixels of viewport width. */
export const WINDOW_WIDTHS = { medium: 600, expanded: 1024, large: 1280 } as const;

/** The media query each class above compact starts at. */
export const WINDOW_QUERIES = {
  medium: `(min-width: ${String(WINDOW_WIDTHS.medium)}px) and (min-height: ${String(MIN_TALL_HEIGHT)}px)`,
  expanded: `(min-width: ${String(WINDOW_WIDTHS.expanded)}px) and (min-height: ${String(MIN_TALL_HEIGHT)}px)`,
  large: `(min-width: ${String(WINDOW_WIDTHS.large)}px) and (min-height: ${String(MIN_TALL_HEIGHT)}px)`,
} as const;

/** The class this window is in right now. */
export function windowClassNow(): WindowClass {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return 'compact';
  if (window.matchMedia(WINDOW_QUERIES.large).matches) return 'large';
  if (window.matchMedia(WINDOW_QUERIES.expanded).matches) return 'expanded';
  if (window.matchMedia(WINDOW_QUERIES.medium).matches) return 'medium';
  return 'compact';
}

/** Whether a class is at least as roomy as another. */
export function atLeast(current: WindowClass, wanted: WindowClass): boolean {
  const order: readonly WindowClass[] = ['compact', 'medium', 'expanded', 'large'];
  return order.indexOf(current) >= order.indexOf(wanted);
}

/**
 * The window class, kept current as the window is resized, a tablet is
 * turned or a desktop window is snapped to half the screen. It is read
 * synchronously on the first render, so a wide window never paints the
 * phone layout first.
 */
export function useWindowClass(): WindowClass {
  const [current, setCurrent] = useState<WindowClass>(windowClassNow);

  useEffect(() => {
    if (typeof window.matchMedia !== 'function') return;
    const lists = Object.values(WINDOW_QUERIES).map((query) => window.matchMedia(query));
    const update = (): void => {
      setCurrent(windowClassNow());
    };
    for (const list of lists) list.addEventListener('change', update);
    update();
    return () => {
      for (const list of lists) list.removeEventListener('change', update);
    };
  }, []);

  return current;
}

/** A mouse or a trackpad: something that can hover and point precisely. */
export const FINE_POINTER_QUERY = '(hover: hover) and (pointer: fine)';

/**
 * Whether to show keyboard shortcuts: a tablet or a computer window with a
 * mouse or trackpad, which nearly always means a keyboard too. A phone
 * never, and nor a small window, which keeps the phone's look whatever it
 * runs on.
 */
export function useShowsKeys(): boolean {
  const size = useWindowClass();
  const [fine] = useState(
    () => typeof window.matchMedia === 'function' && window.matchMedia(FINE_POINTER_QUERY).matches,
  );
  return fine && atLeast(size, 'medium');
}
