/**
 * The one word a visitor types on the introduction, carried through sign-up
 * to the first-word step of onboarding.
 *
 * It has to survive the sign-up form, and on the web Google's redirect,
 * which leaves the page. So it rides in sessionStorage under one key
 * (`lexpad.introWord`, the exception the "No data in localStorage" rule in
 * apps/web/CLAUDE.md names): one tab, gone when the tab closes, and read and
 * deleted by onboarding at once. The router state carries it too, between
 * the intro's own steps, so Back and a reload keep it.
 *
 * Storage can be blocked (a private window with site data refused). The
 * flow still works then: the word is kept in memory for this page, which
 * covers a password or in-app Google sign-up, and only a full redirect
 * forgets it. Nothing about the word is ever sent anywhere before an
 * account exists.
 */

const KEY = 'lexpad.introWord';

/**
 * The longest headword the API takes (`WordCore.headword.maxLength` in
 * contracts/openapi.yaml). Repeated here because the input must stop at it
 * before there is an account to ask; counted in characters, not UTF-16
 * units, so an emoji or a Persian letter is never cut in half.
 */
export const HEADWORD_MAX = 200;

/** The word kept for this page when sessionStorage refuses it. */
let memory: string | undefined;

/**
 * The word as it will be saved: whitespace at the ends trimmed, any run of
 * spaces or line breaks inside (a pasted sentence) made one space, and cut
 * at the headword limit. A phrase is taken as it is: what the learner wrote
 * down is theirs to keep.
 */
export function normalizeIntroWord(raw: string): string {
  const flat = raw.replace(/\s+/gu, ' ').trim();
  const chars = Array.from(flat);
  return chars.length > HEADWORD_MAX ? chars.slice(0, HEADWORD_MAX).join('').trim() : flat;
}

/** Whether a typed text can become a card: it needs at least one letter in any script. */
export function canBeCard(raw: string): boolean {
  return /\p{L}/u.test(normalizeIntroWord(raw));
}

/** Keeps the word for the sign-up that follows. An empty or letterless text clears it. */
export function saveIntroWord(raw: string): void {
  const word = canBeCard(raw) ? normalizeIntroWord(raw) : undefined;
  memory = word;
  try {
    if (word === undefined) sessionStorage.removeItem(KEY);
    else sessionStorage.setItem(KEY, word);
  } catch {
    // Storage blocked: the copy in memory carries it as far as it can.
  }
}

/** The kept word, if any, without forgetting it (the sign-up title reads it). */
export function peekIntroWord(): string | undefined {
  const word = readStored() ?? memory;
  // Checked again on the way out: anything could have written the key.
  return word !== undefined && canBeCard(word) ? normalizeIntroWord(word) : undefined;
}

function readStored(): string | undefined {
  try {
    return sessionStorage.getItem(KEY) ?? undefined;
  } catch {
    return undefined;
  }
}

/** Reads the kept word and forgets it: onboarding (or the add sheet) takes it exactly once. */
export function takeIntroWord(): string | undefined {
  const word = peekIntroWord();
  clearIntroWord();
  return word;
}

/** Forgets the word ("Skip for now"). */
export function clearIntroWord(): void {
  memory = undefined;
  try {
    sessionStorage.removeItem(KEY);
  } catch {
    // Nothing stored where nothing can be stored.
  }
}

/** A word carried in router state, checked like anything else that arrives from outside. */
export function wordFromState(state: unknown): string | undefined {
  const word = (state as { word?: unknown } | null)?.word;
  return typeof word === 'string' && canBeCard(word) ? normalizeIntroWord(word) : undefined;
}
