import { useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Spinner } from '@/components/ui/Spinner.js';
import { t } from '@/i18n/index.js';
import { consumeOAuthState } from './oauthState.js';
import { useAuth } from './session.js';
import { takeReturnPath } from './returnPath.js';

/**
 * Where Google returns the user. The code goes straight to the backend for
 * exchange; this component checks the state nonce, reads the code off the URL
 * and waits.
 */
export function GoogleCallback(): React.JSX.Element {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const { signInWithGoogle } = useAuth();
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    started.current = true;
    const code = params.get('code');
    // A code that did not come back with this browser's own state is not ours to use.
    if (code === null || !consumeOAuthState(params.get('state'))) {
      void navigate('/auth', { replace: true });
      return;
    }
    void signInWithGoogle({ code }).then(() => {
      void navigate(takeReturnPath() ?? '/', { replace: true });
    });
  }, [params, navigate, signInWithGoogle]);

  return <Spinner label={t('state.loading')} />;
}
