import { useEffect, useState } from 'react';
import { cx } from '@/lib/cx.js';
import styles from './Skeleton.module.css';

/**
 * How long a read may take before it is worth saying anything about it.
 *
 * Every read in this app is from the local database and nearly all of them
 * land in a few milliseconds. A placeholder shown immediately would appear
 * and vanish within one frame, which reads as a flicker and is worse than
 * the blank it replaced. Below this, nothing is drawn at all.
 */
const QUIET_MS = 180;

/**
 * The shape of what is coming, instead of a spinner in the middle of an
 * empty screen.
 *
 * A spinner says "wait" and nothing else. A placeholder in the shape of the
 * screen says what is arriving and reserves its space, so the page does not
 * jump when it does. Marked `aria-hidden` and paired with a live region by
 * the caller: a screen reader should hear "loading", not a description of
 * some grey rectangles.
 */
export function Skeleton({
  lines = 3,
  className,
}: {
  /** How many bars to draw under the title bar. */
  lines?: number;
  className?: string | undefined;
}): React.JSX.Element | null {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const timer = window.setTimeout(() => {
      setShow(true);
    }, QUIET_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, []);

  if (!show) return null;

  return (
    <div className={cx(styles.wrap, className)} aria-hidden="true">
      <span className={cx(styles.bar, styles.title)} />
      {Array.from({ length: lines }, (_, index) => (
        <span
          key={index}
          className={cx(styles.bar, index === lines - 1 && styles.short)}
          // Staggered so the sweep reads as one surface being lit across,
          // not as several bars each doing their own thing.
          style={{ animationDelay: `${String(index * 90)}ms` }}
        />
      ))}
    </div>
  );
}
