/** What the settings screen reads, all of it local. */
import { LANGUAGES, LANGUAGE_INFO, defaultSettings, type LanguageCode, type Settings } from '@lexpad/core';
import { countWords, getActiveNotebook, listNotebooks, listWords, loadSettings } from '@/db/repo.js';
import type { StoredNotebook } from '@/db/schema.js';

export interface SettingsData {
  settings: Settings;
  notebook: StoredNotebook | undefined;
  wordCount: number;
  /**
   * Every notebook on the account. There is usually one; a second appears
   * when somebody copies a notebook that was shared with them, and the row
   * that switches between them only exists once there is a choice to make.
   */
  notebooks: StoredNotebook[];
}

export const LOADING: SettingsData = {
  settings: defaultSettings(),
  notebook: undefined,
  wordCount: 0,
  notebooks: [],
};

export async function loadSettingsScreen(): Promise<SettingsData> {
  const notebook = await getActiveNotebook();
  return {
    settings: (await loadSettings()) ?? defaultSettings(),
    notebook,
    wordCount: notebook ? await countWords(notebook.id) : 0,
    notebooks: await listNotebooks(),
  };
}

/** The word list the prototype copies to the clipboard: one word per line. */
export async function wordListText(notebookId: string): Promise<string> {
  const words = await listWords(notebookId);
  return words
    .map((word) => {
      const meaning = word.meanings?.[0]?.meaning ?? '';
      return meaning === '' ? word.headword : `${word.headword} — ${meaning}`;
    })
    .join('\n');
}

/**
 * Each language named twice, as the prototype's pickers show it: in English
 * so it can be recognised, and in itself so it can be found.
 */
export const LANGUAGES_TABLE: Record<LanguageCode, { name: string; native: string }> = Object.fromEntries(
  LANGUAGES.map((code) => [code, { name: LANGUAGE_INFO[code].name, native: LANGUAGE_INFO[code].native }]),
) as Record<LanguageCode, { name: string; native: string }>;

/**
 * The two languages the suggested row always opens with, in this order.
 *
 * Not a guess and not a ranking: Lexpad teaches English, and it is written
 * for Persian speakers — Pro is free on a Persian notebook. So these two are
 * the answer far more often than any signal about the device could say, and
 * they sit above the device's own languages rather than below them. Every
 * other language reaches the row through the device or the list below.
 */
export const PINNED_LANGUAGES: readonly LanguageCode[] = ['en', 'fa'];

/**
 * The languages most people pick, used to fill the suggested row after the
 * pinned two and whatever the device itself names.
 *
 * The order here is by how many people speak or learn each one, and it is a
 * fallback: somebody whose device says Kazakh sees Kazakh before any of it.
 */
export const POPULAR_LANGUAGES: readonly LanguageCode[] = [
  'en',
  'es',
  'zh',
  'hi',
  'ar',
  'fr',
  'pt',
  'ru',
  'de',
  'ja',
  'it',
  'ko',
  'tr',
];

/** Every language, popular ones first and the rest by English name. */
function inDisplayOrder(): readonly LanguageCode[] {
  const rest = LANGUAGES.filter((code) => !POPULAR_LANGUAGES.includes(code)).sort((a, b) =>
    LANGUAGE_INFO[a].name.localeCompare(LANGUAGE_INFO[b].name),
  );
  return [...POPULAR_LANGUAGES, ...rest];
}

/** Languages a notebook can be learning. */
export const TARGET_LANGUAGES: readonly LanguageCode[] = inDisplayOrder();

/** Languages meanings can be written in. */
export const MEANING_LANGUAGES: readonly LanguageCode[] = inDisplayOrder();

/** The English name, for prose that mentions a language. */
export const LANGUAGE_NAMES: Record<LanguageCode, string> = Object.fromEntries(
  LANGUAGES.map((code) => [code, LANGUAGE_INFO[code].name]),
) as Record<LanguageCode, string>;
