/**
 * What the sidebar shows besides the five places: the notebook in view and
 * two numbers from Today. Read locally, like every screen, and the same way
 * Today reads them (`today/data.ts`), so the sidebar and the screen beside
 * it can never disagree about how much is due.
 */
import { dayIndex, effectiveStreak, activeToday as isActiveToday } from '@lexpad/core';
import { inView, listNotebooks, listWords, loadStreak } from '@/db/repo.js';
import type { StoredNotebook } from '@/db/schema.js';
import { localTimeZone } from '@/lib/format.js';
import { cappedDue } from '@/features/schedule/capped.js';

export interface SidebarData {
  /** The notebook being shown, or the default one with everything in view. */
  notebook: StoredNotebook | undefined;
  /** Every notebook is in view. */
  all: boolean;
  /** How many notebooks the account has. */
  notebooks: number;
  /** Reviews due today in what is in view: Today's own "to review". */
  due: number;
  streak: number;
  /** Today has already kept the streak. */
  streakActive: boolean;
}

/** Nothing drawn until the first read lands: no zero that is not real. */
export const SIDEBAR_LOADING = undefined;

export async function loadSidebar(now: Date = new Date()): Promise<SidebarData> {
  const today = dayIndex(now, localTimeZone());
  const [view, everything, streak] = await Promise.all([inView(), listNotebooks(), loadStreak()]);
  const lists = await Promise.all(view.notebooks.map((one) => listWords(one.id)));
  return {
    notebook: view.showing,
    all: view.all,
    notebooks: everything.length,
    // Under each notebook's daily review limit, as Today counts it.
    due: view.showing === undefined ? 0 : (await cappedDue(view.notebooks, lists, today)).due,
    streak: effectiveStreak(streak, today),
    streakActive: isActiveToday(streak, today),
  };
}
