import { cx } from '@/lib/cx.js';
import styles from './Screen.module.css';

interface ScreenProps {
  title?: string | undefined;
  subtitle?: string | undefined;
  /** Rendered opposite the title, for a single action or a count. */
  aside?: React.ReactNode;
  /** Fills the viewport with no room for the tab bar, for sessions. */
  full?: boolean;
  children: React.ReactNode;
}

/** The one-column layout every screen sits in: centred, safe-area aware. */
export function Screen({ title, subtitle, aside, full = false, children }: ScreenProps): React.JSX.Element {
  return (
    <main className={cx(styles.screen, full && styles.full)}>
      {title !== undefined && (
        <header className={styles.header}>
          <div>
            <h1 className={styles.title}>{title}</h1>
            {subtitle !== undefined && <p className={styles.subtitle}>{subtitle}</p>}
          </div>
          {aside}
        </header>
      )}
      {children}
    </main>
  );
}
