/**
 * The messages the connect page and the browser extension's content script
 * exchange, on that window only. The extension announces itself when the
 * page loads, receives the sealed session once the user allows it (see
 * sealSession.ts), and confirms it kept it. The extension repository mirrors
 * these names.
 */
export const CONNECT_MESSAGES = {
  /** The page asks whether an extension is listening; `ready` is the answer. */
  ping: 'lexpad:extension-ping',
  ready: 'lexpad:extension-ready',
  /** The session sealed to the extension's key. Never a session in the clear. */
  sealed: 'lexpad:extension-sealed',
  /**
   * The session in the clear, as extension 0.1.x expects it. Posted only when
   * the address carries no `key`, which only 0.1.x opens. Remove this, and the
   * branch in ConnectExtension that uses it, once the sealed handoff (0.2.0)
   * is live in every store: everything posted on this window reaches every
   * listener on the page.
   */
  legacySession: 'lexpad:extension-session',
  connected: 'lexpad:extension-connected',
} as const;
