/**
 * What the practice modes read (SRS v2 phase E), all of it local: the
 * notebook on screen, its words, the learner's typing strictness, meta
 * `srs` (which modes are switched on) and meta `modes` (No timer, best
 * Speed rounds).
 *
 * Every mode drills only the learner's own words: this reads the notebook
 * and nothing else.
 */
import {
  BUILDER_MAX_TILES,
  BUILDER_MIN_TILES,
  DRILL_MIN,
  MATCH_MIN_WORDS,
  MODES,
  SPEED_CHOICES,
  builderSentence,
  collocationFeasible,
  dayIndex,
  defaultSettings,
  dictationEligible,
  exampleSentences,
  firstMeaning,
  matchFeasible,
  speedFeasible,
  type GradingMode,
  type LanguageCode,
  type ModeId,
  type ModeWord,
  type Word,
} from '@lexpad/core';
import type { IconName } from '@/components/ui/Icon.js';
import { getActiveNotebook, listWords, loadSettings } from '@/db/repo.js';
import { db, getMeta, setMeta, type MetaShape, type StoredNotebook } from '@/db/schema.js';
import { SRS_OFF, loadSrsView, shows, type SrsView } from '@/features/schedule/data.js';
import { localTimeZone } from '@/lib/format.js';

/** A notebook word as the modes see it. Retired words are left out by the caller. */
export function toModeWord(word: Word): ModeWord {
  return {
    id: word.id,
    headword: word.headword,
    meaning: firstMeaning(word).trim(),
    examples: exampleSentences(word),
    collocations: (word.collocations ?? []).filter((phrase) => phrase.trim() !== ''),
    ...(word.progress === undefined ? {} : { box: word.progress.box, dueDay: word.progress.dueDay }),
  };
}

/** Why a mode cannot run here, or undefined when it can. */
export type Blocker = 'few' | 'noVoice' | 'noMic';

/** Everything a mode screen and the picker draw. */
export interface ModesView {
  /** False until the first IndexedDB read has landed. */
  ready: boolean;
  srs: SrsView;
  /**
   * Whether the server has ever been asked about SRS v2 on this device. A
   * learner who has just signed in may open a link before the first answer
   * lands, and "not asked yet" must not be read as "switched off".
   */
  srsKnown: boolean;
  notebook: StoredNotebook | undefined;
  /** The notebook's practisable words: not retired. */
  words: ModeWord[];
  typedGrading: GradingMode;
  /** Today's day index in this device's zone. */
  today: number;
  prefs: NonNullable<MetaShape['modes']>;
}

export const MODES_LOADING: ModesView = {
  ready: false,
  srs: SRS_OFF,
  srsKnown: false,
  notebook: undefined,
  words: [],
  typedGrading: defaultSettings().typedGrading,
  today: 0,
  prefs: { noTimer: false, speedBest: {} },
};

/** The modes this account and client may see, in the spec's order. */
export function shownModes(srs: SrsView): ModeId[] {
  return MODES.filter((mode) => shows(srs, mode));
}

/**
 * Reads what the modes need. The notebook's words are read only when at
 * least one mode is switched on, so the Decks screen of an account without
 * them costs exactly what it did.
 */
export async function loadModes(now: Date = new Date()): Promise<ModesView> {
  const [srs, asked, notebook, settings, prefs] = await Promise.all([
    loadSrsView(),
    getMeta('srs'),
    getActiveNotebook(),
    loadSettings(),
    getMeta('modes'),
  ]);
  const base = {
    ready: true,
    srs,
    srsKnown: asked !== null,
    notebook,
    typedGrading: settings?.typedGrading ?? defaultSettings().typedGrading,
    today: dayIndex(now, localTimeZone()),
    prefs: prefs ?? { noTimer: false, speedBest: {} },
  };
  if (notebook === undefined || shownModes(srs).length === 0) return { ...base, words: [] };
  const words = await listWords(notebook.id);
  return {
    ...base,
    words: words.filter((word) => word.progress?.retired !== true).map(toModeWord),
  };
}

/** The words a drill can use, for the modes that ask one word at a time. */
export function drillWords(mode: ModeId, words: readonly ModeWord[], lang: LanguageCode): ModeWord[] {
  switch (mode) {
    case 'dictation':
      return words.filter(dictationEligible);
    case 'builder':
      return words.filter((word) => builderSentence(word, lang) !== undefined);
    case 'sayIt':
    case 'sentence':
      return words.filter((word) => word.meaning !== '');
    case 'match':
    case 'speed':
    case 'collocation':
      return [...words];
  }
}

/**
 * Whether the notebook can feed a mode (spec 6.9): Match and Speed need
 * enough words with different meanings, the drills a few usable words,
 * Collocations saved collocations, Builder examples of the right length.
 * Dictation's voice and Say it's microphone are the device's, checked by
 * the screen.
 */
export function canFeed(mode: ModeId, words: readonly ModeWord[], lang: LanguageCode): boolean {
  switch (mode) {
    case 'match':
      return matchFeasible(words);
    case 'speed':
      return speedFeasible(words);
    case 'collocation':
      return collocationFeasible(words);
    default:
      return drillWords(mode, words, lang).length >= DRILL_MIN;
  }
}

/** What an empty mode says, in its own words (EmptyState rule). */
export function fewWordsBody(mode: ModeId): { key: string; values: Record<string, number> } {
  switch (mode) {
    case 'match':
      return { key: 'modes.fewMatch', values: { count: MATCH_MIN_WORDS } };
    case 'speed':
      return { key: 'modes.fewSpeed', values: { count: SPEED_CHOICES } };
    case 'dictation':
      return { key: 'modes.fewDictation', values: { count: DRILL_MIN } };
    case 'builder':
      return { key: 'modes.fewBuilder', values: { min: BUILDER_MIN_TILES, max: BUILDER_MAX_TILES } };
    case 'collocation':
      return { key: 'modes.fewCollocation', values: {} };
    case 'sayIt':
    case 'sentence':
      return { key: 'modes.fewWords', values: { count: DRILL_MIN } };
  }
}

/**
 * Saves the modes' own preferences. Read-modify-write inside the call, so
 * a best score and the No timer switch saved together both land.
 */
export async function saveModePrefs(
  change: (prefs: NonNullable<MetaShape['modes']>) => NonNullable<MetaShape['modes']>,
): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const current = (await getMeta('modes')) ?? { noTimer: false, speedBest: {} };
    await setMeta('modes', change(current));
  });
}

/** Each mode's icon. Today's "Games and drills" row and the sidebar's Games use `grid`, Match's own. */
export const MODE_ICONS: Record<ModeId, IconName> = {
  match: 'grid',
  speed: 'flame',
  dictation: 'headphones',
  builder: 'shuffle',
  collocation: 'cards',
  sayIt: 'mic',
  sentence: 'pencil',
};

/** The path a mode opens at. */
export function modePath(mode: ModeId): string {
  return `/practice/${mode}`;
}

/**
 * The games and drills screen, where every mode is picked and where a mode
 * goes back to. Its own route since 2026-10-09 (tester feedback: Today's
 * "Games and drills" and "Decks" opened the same screen).
 */
export const GAMES_PATH = '/games';

/**
 * The history state a mode is opened with from the games screen, so that
 * leaving it pops back to that screen instead of stacking another copy.
 */
export const FROM_GAMES = { fromGames: true } as const;

/**
 * Why a mode switched on for the account cannot run here, `waiting` while
 * the device is still being asked whether it can listen, or undefined when
 * it can run. The order is the order a learner can do something about it:
 * words first, then the device.
 */
export function blockerOf(
  mode: ModeId,
  words: readonly ModeWord[],
  lang: LanguageCode,
  device: { canSpeak: boolean; canListen: boolean | undefined },
): Blocker | 'waiting' | undefined {
  if (!canFeed(mode, words, lang)) return 'few';
  if (mode === 'dictation' && !device.canSpeak) return 'noVoice';
  if (mode === 'sayIt') {
    if (device.canListen === undefined) return 'waiting';
    if (!device.canListen) return 'noMic';
  }
  return undefined;
}
