import { platform } from './platform/index.js';
import type { ApiClientConfig } from '@/api/types.js';

/**
 * Whether this build is too old to keep using.
 *
 * The rule comes from the server, because "everyone on 1.0.28 has the bug
 * that loses their words, stop them" is a decision somebody makes in an
 * afternoon, and a number written into this bundle would make it a release.
 *
 * Every uncertainty here resolves to "carry on". A missing rule, a platform
 * nobody set, a version this build cannot report — none of them stop
 * anybody. The failure this guards against is locking somebody out of their
 * own notebook over a typo in a flag, which is worse than one more day on an
 * old build.
 */

export type UpdateVerdict = 'ok' | 'offer' | 'block';

/**
 * Compares two dotted versions part by part, as numbers.
 *
 * Never as strings: "1.0.9" sorts after "1.0.10" alphabetically and is older
 * in every way that matters, so a string comparison would wave through
 * exactly the builds being chased. A missing part is zero, so 1.0 and 1.0.0
 * are the same build, and anything unreadable is zero rather than an error —
 * a version is a label somebody typed into a flag, and half of them have a
 * "v" on the front.
 */
export function older(a: string, b: string): boolean {
  const parse = (v: string): number[] => {
    const clean =
      v
        .trim()
        .replace(/^v/i, '')
        .split(/[-+\s]/)[0] ?? '';
    if (clean === '') return [];
    return clean.split('.').map((part) => {
      const n = Number.parseInt(part, 10);
      return Number.isNaN(n) ? 0 : n;
    });
  };
  const av = parse(a);
  const bv = parse(b);
  for (let i = 0; i < Math.max(av.length, bv.length); i += 1) {
    const x = av[i] ?? 0;
    const y = bv[i] ?? 0;
    if (x !== y) return x < y;
  }
  return false;
}

/** What this client should tell its user, given the server's rules. */
export function verdictFor(
  update: ApiClientConfig['update'],
  client: string,
  version: string,
): { verdict: UpdateVerdict; url: string } {
  const none = { verdict: 'ok' as const, url: '' };
  if (update === undefined) return none;
  const rule = update[client];
  if (rule === undefined) return none;
  // A build that cannot say what it is is a development build, or one older
  // than this field. Neither is somebody to lock out.
  if (version === '' || version === 'dev') return none;
  const url = rule.url ?? '';
  if (older(version, rule.minimum)) return { verdict: 'block', url };
  if (older(version, rule.wanted)) return { verdict: 'offer', url };
  return none;
}

/**
 * Which rule this build reads.
 *
 * The extension is its own client with its own store listing, and it never
 * runs this code — it calls the API directly from its own bundle. What runs
 * here is the web app, or the same web app inside a native shell, and the
 * shell is what makes an Android build an Android build.
 */
export function clientName(): string {
  return platform.env.platform;
}

/** This build's own version, as the shell or the bundle reports it. */
export function clientVersion(): string {
  return platform.env.appVersion;
}
