/**
 * The system bars, pinned.
 *
 * `env(safe-area-inset-*)` is the browser's answer to "how much of the
 * viewport do the notch, the status bar and the home indicator cover", and
 * on both shells it is unreliable in a different way.
 *
 * On iOS WKWebView the top inset is reported against the visual viewport,
 * so it shrinks while the page is scrolled. Anything that reads it live —
 * a sticky header's own padding, most of all — loses its inset the moment
 * somebody scrolls, and the title ends up under the clock. That is what
 * this exists to stop: the inset is measured once while the page is at rest
 * and written to `--safe-area-inset-*` on the root, and `--safe-top` and
 * `--safe-bottom` in `tokens.css` prefer those over `env()`.
 *
 * On Android WebView `env()` reports the display cutout and nothing else, so
 * a phone with no notch answers zero for a status bar that is really there.
 * The shell writes the true insets to the same two variables; this module
 * never lowers a value the shell has set, so the two cannot fight.
 *
 * The largest value seen in an orientation wins. A measurement taken mid-
 * scroll or mid-keyboard is always too small, never too large, so taking
 * the maximum is what makes a wrong reading harmless. Turning the phone
 * moves the bars, so each orientation starts its own measurement.
 */

const SIDES = ['top', 'right', 'bottom', 'left'] as const;
type Side = (typeof SIDES)[number];

/** The largest inset seen since the last orientation change. */
const seen = new Map<Side, number>();
let orientation: 'portrait' | 'landscape' | null = null;

/**
 * Reads the four insets by asking the browser to resolve `env()` for us.
 * A fixed, empty, invisible probe is the only way: `env()` is a CSS value
 * with no JavaScript reader, so something has to have it applied before
 * `getComputedStyle` can report a pixel length.
 */
function measure(): Record<Side, number> {
  const probe = document.createElement('div');
  probe.setAttribute('aria-hidden', 'true');
  probe.style.cssText = [
    'position:fixed',
    'top:0',
    'left:0',
    'width:0',
    'height:0',
    'visibility:hidden',
    'pointer-events:none',
    'padding-top:env(safe-area-inset-top,0px)',
    'padding-right:env(safe-area-inset-right,0px)',
    'padding-bottom:env(safe-area-inset-bottom,0px)',
    'padding-left:env(safe-area-inset-left,0px)',
  ].join(';');
  document.body.appendChild(probe);
  const style = getComputedStyle(probe);
  const read = (side: Side): number => Number.parseFloat(style.getPropertyValue(`padding-${side}`)) || 0;
  const insets = { top: read('top'), right: read('right'), bottom: read('bottom'), left: read('left') };
  probe.remove();
  return insets;
}

/**
 * Which way up the device is.
 *
 * Asked of the screen rather than worked out from the viewport. Comparing
 * innerWidth with innerHeight looks equivalent and is not: a sheet opening
 * or closing resizes the viewport for a frame or two, and a tall narrow
 * phone can pass through a shape that reads as landscape on the way. That
 * counted as turning the phone, which threw away the remembered inset and
 * wrote whatever the next reading said — and the notebook's sticky header
 * lost its clearance under the clock for the rest of the session.
 *
 * `screen.orientation` does not move until the device really does.
 */
function currentOrientation(): 'portrait' | 'landscape' {
  // Typed as optional because the DOM library says it always exists, and
  // in a web view old enough it does not.
  const orientation = globalThis.screen.orientation as ScreenOrientation | undefined;
  const type = orientation?.type;
  if (typeof type === 'string') return type.startsWith('landscape') ? 'landscape' : 'portrait';
  return window.innerHeight >= window.innerWidth ? 'portrait' : 'landscape';
}

/**
 * Takes one reading and keeps it if it is the largest so far.
 *
 * A viewport with no size teaches nothing. A sheet opening was enough to
 * produce one, and everything measured in it is zero -- including the
 * width, which made a portrait phone look briefly like a landscape one.
 * That cleared the remembered maximum and wrote the zero, and the
 * notebook's header lost its inset for the rest of the session.
 *
 * Whatever is already on the root counts as a reading of its own, so a
 * value the shell published survives a measurement that cannot see it.
 * Turning the phone is the one thing that throws that away, because the
 * bars really have moved; the shell publishes again on the same event, and
 * one more reading next frame catches the bars once they have settled.
 */
function apply(): void {
  if (window.innerWidth <= 0 || window.innerHeight <= 0) return;
  const now = currentOrientation();
  const turned = orientation !== null && now !== orientation;
  orientation = now;

  const root = document.documentElement;
  if (turned) {
    seen.clear();
    for (const side of SIDES) root.style.removeProperty(`--safe-area-inset-${side}`);
  }

  const insets = measure();
  for (const side of SIDES) {
    const name = `--safe-area-inset-${side}`;
    const already = Number.parseFloat(root.style.getPropertyValue(name));
    const largest = Math.max(insets[side], seen.get(side) ?? 0, Number.isFinite(already) ? already : 0);
    seen.set(side, largest);
    root.style.setProperty(name, `${largest}px`);
  }
  if (turned) requestAnimationFrame(apply);
}

/**
 * Starts pinning the insets. Called once at boot, before the first render,
 * so no screen ever lays out against a value that is about to change.
 */
export function startSafeArea(): void {
  apply();
  // A late reading catches the shell finishing its own set-up, and a phone
  // that reports zero until the first frame is on screen.
  requestAnimationFrame(apply);
  window.addEventListener('orientationchange', apply);
  window.addEventListener('resize', apply);
}
