/**
 * What the schedule page, the word page and the notebook read about SRS v2,
 * all of it local: meta `srs` (GET /me/srs), the notebook's saved settings
 * and the effective schedule the engine runs on.
 */
import type { EffectiveSchedule } from '@lexpad/core';
import type { ApiOlderDevice, ApiScheduleDefaults } from '@/api/types.js';
import { getActiveNotebook, listNotebooks, loadSchedule, loadSavedSchedule } from '@/db/repo.js';
import { getMeta, type StoredNotebook, type StoredSchedule } from '@/db/schema.js';

/** The SRS v2 features this client shows, by name; all off when the server said nothing. */
export interface SrsView {
  /** The SRS v2 screens are on for this account and client. */
  enabled: boolean;
  /** One switch per feature; a missing one is off. */
  features: Readonly<Record<string, boolean>>;
  /** The account's apps that show changes only after they sync. */
  olderDevices: readonly ApiOlderDevice[];
  /** The values the pickers offer. */
  choices: { reviewCap: readonly number[]; leechThreshold: readonly number[]; retention: RetentionPresets };
}

/** Smart's three named targets, in percent. */
export interface RetentionPresets {
  relaxed: number;
  balanced: number;
  exam: number;
}

/**
 * The spec's targets (SRS v2 §1 C), for a server that names none. The
 * server's own fallback is the same (`learn.DefaultRetentionPresets`); a
 * server that offers Smart always sends its presets, so these only fill the
 * shape for one that predates them.
 */
export const DEFAULT_RETENTION_PRESETS: RetentionPresets = { relaxed: 85, balanced: 90, exam: 95 };

/**
 * The range a custom target may take: the API contract's bounds for
 * `NotebookSchedule.retention` (and the database's CHECK), not a tunable.
 */
export const RETENTION_MIN = 80;
export const RETENTION_MAX = 97;

/** Nothing on: today's app. */
export const SRS_OFF: SrsView = {
  enabled: false,
  features: {},
  olderDevices: [],
  choices: { reviewCap: [], leechThreshold: [], retention: DEFAULT_RETENTION_PRESETS },
};

/** Reads meta `srs` as the screens use it. */
export async function loadSrsView(): Promise<SrsView> {
  const srs = await getMeta('srs');
  const state = srs?.state;
  if (state === null || state === undefined) return SRS_OFF;
  return {
    enabled: state.enabled,
    features: state.features,
    olderDevices: state.olderDevices,
    choices: {
      reviewCap: state.choices.reviewCap,
      leechThreshold: state.choices.leechThreshold,
      retention: state.choices.retentionPresets ?? DEFAULT_RETENTION_PRESETS,
    },
  };
}

/** Whether one SRS v2 feature shows here. */
export function shows(view: SrsView, feature: string): boolean {
  return view.enabled && view.features[feature] === true;
}

/** Everything the schedule page draws. */
export interface SchedulePageData {
  /** False until the first IndexedDB read has landed. */
  ready: boolean;
  notebook: StoredNotebook | undefined;
  notebooks: number;
  saved: StoredSchedule | undefined;
  schedule: EffectiveSchedule | undefined;
  srs: SrsView;
  /** The one-time card introducing Smart was put away on this device. */
  smartIntroSeen: boolean;
  /** The values a notebook nobody has set up runs on, from the server; undefined without SRS v2. */
  defaults: ApiScheduleDefaults | undefined;
  /** "More options" was left open here last time (the new learner's journey). */
  moreOpen: boolean;
}

export const SCHEDULE_LOADING: SchedulePageData = {
  ready: false,
  notebook: undefined,
  notebooks: 0,
  saved: undefined,
  schedule: undefined,
  srs: SRS_OFF,
  smartIntroSeen: true,
  defaults: undefined,
  moreOpen: false,
};

/** Reads the schedule page for the notebook being shown. */
export async function loadSchedulePage(): Promise<SchedulePageData> {
  const [notebook, notebooks, srs, smartIntroSeen, stored, more] = await Promise.all([
    getActiveNotebook(),
    listNotebooks(),
    loadSrsView(),
    getMeta('smartIntroSeen'),
    getMeta('srs'),
    getMeta('moreOptions'),
  ]);
  const shared = {
    ready: true,
    notebook,
    notebooks: notebooks.length,
    srs,
    smartIntroSeen,
    defaults: stored?.state?.defaults,
    moreOpen: more?.schedule === true,
  };
  if (notebook === undefined) return { ...shared, saved: undefined, schedule: undefined };
  const [saved, schedule] = await Promise.all([loadSavedSchedule(notebook.id), loadSchedule(notebook.id)]);
  return { ...shared, saved, schedule };
}
