import { useEffect, useRef, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { auth as authApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { toCurrentUser, useAuth } from './session.js';
import styles from './SignIn.module.css';

type Outcome = 'working' | 'done' | 'invalid' | 'offline';

/**
 * Where the confirmation link lands. The token goes to the API once; a
 * signed-in account picks up its confirmed state right away, and anyone
 * else is sent to sign in.
 */
export function VerifyEmail(): React.JSX.Element {
  const [params] = useSearchParams();
  const token = params.get('token') ?? '';
  // A link without a token is refused before anything is sent.
  const [outcome, setOutcome] = useState<Outcome>(token === '' ? 'invalid' : 'working');
  const started = useRef(false);
  const status = useAuth((state) => state.status);
  const user = useAuth((state) => state.user);
  const setUser = useAuth((state) => state.setUser);

  useEffect(() => {
    if (started.current || token === '') return;
    started.current = true;
    authApi
      .verifyEmail(token)
      .then(async (confirmed) => {
        // The link may be opened on a device signed in as that account, or
        // on any other; only the former has a profile to update.
        if (user !== null && user.id === confirmed.id) await setUser(toCurrentUser(confirmed));
        setOutcome('done');
      })
      .catch((error: unknown) => {
        setOutcome(isApiError(error, 'offline') ? 'offline' : 'invalid');
      });
  }, [token, user, setUser]);

  const target = status === 'ready' ? '/' : '/auth';
  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <div className={styles.form}>
        <div className={styles.formTitle}>
          {outcome === 'done'
            ? t('auth.verifyDoneTitle')
            : outcome === 'invalid'
              ? t('auth.verifyFailedTitle')
              : t('auth.verifyTitle')}
        </div>
        {outcome === 'working' && <p className={styles.lead}>{t('state.loading')}</p>}
        {outcome === 'done' && (
          <>
            <p className={styles.success} role="status">
              {t('auth.verifyDone')}
            </p>
            <Link to={target} className={styles.submit}>
              {t('auth.verifyContinue')}
            </Link>
          </>
        )}
        {outcome === 'invalid' && (
          <>
            <p className={styles.error} role="alert">
              {t('auth.linkInvalid')}
            </p>
            <Link to={target} className={styles.textLink}>
              {status === 'ready' ? t('auth.verifyContinue') : t('auth.backToSignIn')}
            </Link>
          </>
        )}
        {outcome === 'offline' && (
          <p className={styles.error} role="alert">
            {t('error.offline')}
          </p>
        )}
      </div>
    </main>
  );
}
