/** Solid icons: drawn as a fill, no stroke. */
const FILLED = {
  starOn: <path d="M12 3.5l2.6 5.4 5.9.8-4.3 4.1 1.1 5.9L12 16.9l-5.3 2.8 1.1-5.9-4.3-4.1 5.9-.8z" />,
  flame: (
    <path d="M12 2.5c.6 3.6 2.4 5.6 4.6 7.6 2 1.9 3.4 4 3.4 6.4a8 8 0 0 1-16 0c0-2.1.9-3.7 2.2-5.1.5 1.4 1.4 2.3 2.6 2.7C8.4 10.6 9.3 6.2 12 2.5z" />
  ),
} as const;

export type IconName = keyof typeof STROKE | keyof typeof FILLED;

interface IconProps {
  name: IconName;
  /** Pixel size of the square box. The prototype uses 14 to 24. */
  size?: number;
  /** Stroke width, for the rare icon that needs a heavier line. */
  weight?: number;
  className?: string | undefined;
}

/** One icon, inheriting its colour from the text around it. */
export function Icon({ name, size = 20, weight = 1.8, className }: IconProps): React.JSX.Element {
  const filled = name in FILLED;
  return (
    <svg
      className={cx(styles.icon, className)}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      aria-hidden="true"
      focusable="false"
      {...(filled
        ? { fill: 'currentColor', stroke: 'none' }
        : {
            fill: 'none',
            stroke: 'currentColor',
            strokeWidth: weight,
            strokeLinecap: 'round' as const,
            strokeLinejoin: 'round' as const,
          })}
    >
      {filled ? FILLED[name as keyof typeof FILLED] : STROKE[name as keyof typeof STROKE]}
    </svg>
  );
}

