import { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { INTERVALS } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { WINDOW_QUERIES } from '@/lib/windowClass.js';
import {
  HEADWORD_MAX,
  canBeCard,
  clearIntroWord,
  normalizeIntroWord,
  peekIntroWord,
  saveIntroWord,
  wordFromState,
} from './introWord.js';
import { markIntroSeen } from './seen.js';
import styles from './Intro.module.css';

/**
 * What the router carries through the introduction: where the gate was
 * taking the visitor (sign-in returns them there) and, on the second step,
 * the word that became a card. State rather than component state, so Back
 * and a reload land on the step the visitor was on.
 */
interface IntroState {
  from?: unknown;
  word?: unknown;
}

/** Characters above which the card sets the word smaller: a phrase still fits. */
const LONG_WORD = 16;

/** Lets an RTL or mixed word sit inside an English sentence without reordering it. */
function isolate(word: string): string {
  return `⁨${word}⁩`;
}

/**
 * The first screen a stranger sees, once per device: one question, their
 * own word, and the card it becomes, dropped into box 1 of the five boxes.
 * Then sign-up, titled with that word, and onboarding with it filled in.
 *
 * Nothing here talks to the network and nothing here invents a word: the
 * only word on screen is the one the visitor typed. Sign-in is one tap away
 * in the corner for anyone who already has an account.
 */
export function Intro(): React.JSX.Element {
  const location = useLocation();
  const carried = (location.state as IntroState | null) ?? {};
  const word = wordFromState(carried);
  return word === undefined ? <Welcome from={carried.from} /> : <Landed word={word} from={carried.from} />;
}

/** The bar both steps share: the name, a way back on the second step, and Sign in. */
function Top({ from, onBack }: { from: unknown; onBack?: (() => void) | undefined }): React.JSX.Element {
  const navigate = useNavigate();
  return (
    <header className={styles.top}>
      {onBack === undefined ? (
        <span className={styles.brand}>
          <span className={styles.mark} aria-hidden="true">
            <Icon name="notebook" size={18} weight={2} />
          </span>
          <span className={styles.name}>{t('app.name')}</span>
        </span>
      ) : (
        <button type="button" className={styles.back} aria-label={t('action.back')} onClick={onBack}>
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
      )}
      <button
        type="button"
        className={styles.signIn}
        onClick={() => {
          markIntroSeen();
          // Pushed, not replaced: Back from the form returns here.
          void navigate('/auth', { state: { from } });
        }}
      >
        {t('intro.signIn')}
      </button>
    </header>
  );
}

/** Step one: the question and the field. */
function Welcome({ from }: { from: unknown }): React.JSX.Element {
  const navigate = useNavigate();
  // Back from the card finds the word still typed.
  const [text, setText] = useState(() => peekIntroWord() ?? '');
  const input = useRef<HTMLInputElement>(null);
  const ready = canBeCard(text);
  const preview = ready ? normalizeIntroWord(text) : '';

  // A keyboard on a phone would cover half the screen before anyone has
  // read the question, so the field takes focus only on a wide window.
  useEffect(() => {
    if (typeof window.matchMedia === 'function' && window.matchMedia(WINDOW_QUERIES.expanded).matches)
      input.current?.focus();
  }, []);

  const submit: React.SubmitEventHandler<HTMLFormElement> = (event) => {
    event.preventDefault();
    if (!ready) return;
    const word = normalizeIntroWord(text);
    saveIntroWord(word);
    // Its own history entry, so Back returns to the question.
    void navigate('/intro', { state: { from, word } });
  };

  return (
    <main className={styles.wrap}>
      <Top from={from} />
      <div className={styles.frame}>
        <form className={styles.copy} onSubmit={submit} noValidate>
          <h1 className={styles.title}>{t('intro.welcomeTitle')}</h1>
          <label className={styles.lead} htmlFor="intro-word">
            {t('intro.welcomeLead')}
          </label>
          <input
            ref={input}
            id="intro-word"
            className={styles.input}
            value={text}
            dir="auto"
            placeholder={t('intro.welcomePlaceholder')}
            autoComplete="off"
            autoCapitalize="off"
            autoCorrect="off"
            spellCheck={false}
            enterKeyHint="done"
            onChange={(event) => {
              // Cut at the headword limit by characters, never mid-letter.
              const chars = Array.from(event.target.value);
              setText(
                chars.length > HEADWORD_MAX ? chars.slice(0, HEADWORD_MAX).join('') : event.target.value,
              );
            }}
          />
          <div className={styles.actions}>
            <button type="submit" className={styles.primary} disabled={!ready}>
              {t('intro.makeCard')}
            </button>
            <button
              type="button"
              className={styles.quiet}
              onClick={() => {
                clearIntroWord();
                markIntroSeen();
                void navigate('/auth?mode=signup', { state: { from } });
              }}
            >
              {t('intro.skipForNow')}
            </button>
          </div>
        </form>
        {/* The card takes shape as the word is typed: small above the
            question on a phone, beside the field with the boxes on a wide
            window. A picture of the field, so hidden from screen readers. */}
        <div className={cx(styles.stage, styles.stageWelcome)} aria-hidden="true">
          <Card word={preview} />
          <Ladder word={undefined} />
        </div>
      </div>
    </main>
  );
}

/** Step two: the card, landed in box 1, and the one sentence that explains the boxes. */
function Landed({ word, from }: { word: string; from: unknown }): React.JSX.Element {
  const navigate = useNavigate();
  const heading = useRef<HTMLHeadingElement>(null);
  // A screen reader hears the new step, and Tab starts from it.
  useEffect(() => {
    heading.current?.focus();
  }, []);
  return (
    <main className={styles.wrap}>
      <Top
        from={from}
        onBack={() => {
          void navigate(-1);
        }}
      />
      <div className={cx(styles.frame, styles.frameLanded)}>
        <div className={styles.stage}>
          <Card word={word} />
          <Ladder word={word} />
        </div>
        <div className={styles.copy}>
          <h1 ref={heading} className={cx(styles.title, styles.landedTitle)} tabIndex={-1}>
            {t('intro.landedTitle', { word: isolate(word) })}
          </h1>
          <p className={styles.lead}>{t('intro.landedBody')}</p>
          <div className={styles.actions}>
            <button
              type="button"
              className={styles.primary}
              onClick={() => {
                saveIntroWord(word);
                markIntroSeen();
                void navigate('/auth?mode=signup', { state: { from, word } });
              }}
            >
              {t('intro.keep')}
            </button>
          </div>
        </div>
      </div>
    </main>
  );
}

/** The word as a card, in the session's own card style. Empty, it waits for one. */
function Card({ word }: { word: string }): React.JSX.Element {
  return (
    <div className={styles.card}>
      <span className={styles.cardNew}>{t('session.new')}</span>
      <span
        className={cx(
          styles.cardWord,
          Array.from(word).length > LONG_WORD && styles.cardLong,
          word === '' && styles.cardEmpty,
        )}
        dir="auto"
      >
        {word === '' ? t('intro.cardEmpty') : word}
      </span>
    </div>
  );
}

/**
 * The five boxes with the wait each one adds, from the engine's own
 * intervals. With a word, it drops into box 1 and a faint copy hops up the
 * ladder once to show where it is going; with reduced motion it is simply
 * there, and the drawn track shows the way.
 */
function Ladder({ word }: { word: string | undefined }): React.JSX.Element {
  const wait = (days: number): string =>
    days === 0
      ? t('onboarding.intervalToday')
      : days === 1
        ? t('onboarding.intervalOneDay')
        : t('onboarding.intervalDays', { n: days });
  return (
    <figure className={styles.ladder}>
      <figcaption className="sr-only">{t('intro.ladderLabel')}</figcaption>
      <ol className={styles.rungs}>
        {INTERVALS.map((days, index) => (
          <li key={index} className={styles.rung}>
            <span className={cx(styles.slot, index === 0 && word !== undefined && styles.slotLit)}>
              {index === 0 && word !== undefined && (
                <>
                  <span className={styles.chip} dir="auto">
                    {word}
                  </span>
                  <span className={cx(styles.chip, styles.ghost)} aria-hidden="true" />
                </>
              )}
            </span>
            <span className={styles.rungName}>{t('onboarding.box', { n: index + 1 })}</span>
            <span className={styles.rungWait}>{wait(days)}</span>
          </li>
        ))}
      </ol>
      <span className={styles.track} aria-hidden="true">
        <svg viewBox="0 0 100 8" preserveAspectRatio="none" className={styles.trackLine}>
          <line x1="2" y1="4" x2="96" y2="4" />
        </svg>
        <Icon name="chevronRight" size={14} weight={2.2} className={styles.trackHead} />
      </span>
    </figure>
  );
}
