/**
 * Where a signed-out visitor was heading, so signing in takes them back
 * there with the query string intact (the assistant consent screen needs its
 * `?request=`). The value comes from the address bar, so it is untrusted:
 * only a path on this origin is ever followed, never another site.
 */

/** Any base works: it only exists so a relative path can be parsed and compared. */
const PARSE_BASE = 'https://lexpad.invalid';

/**
 * The same-origin path to return to, or undefined when the value could
 * leave this app. It must start with a single "/" (not "//" or "/\", which
 * browsers read as another host), carry no control characters or spaces,
 * and still resolve to this origin once parsed. What comes back is the
 * parsed path, query and fragment, never the raw string.
 */
export function safeReturnPath(raw: unknown): string | undefined {
  if (typeof raw !== 'string' || raw.length === 0 || raw.length > 2048) return undefined;
  if (!raw.startsWith('/')) return undefined;
  if (raw.startsWith('//') || raw.startsWith('/\\')) return undefined;
  // Tabs and newlines are stripped by URL parsers, which can turn "/\t/evil.com" into "//evil.com".
  if (raw.includes('\\') || /\s/u.test(raw) || hasControl(raw)) return undefined;
  let parsed: URL;
  try {
    parsed = new URL(raw, PARSE_BASE);
  } catch {
    return undefined;
  }
  if (parsed.origin !== PARSE_BASE) return undefined;
  const path = `${parsed.pathname}${parsed.search}${parsed.hash}`;
  return path.startsWith('//') ? undefined : path;
}

function hasControl(text: string): boolean {
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code < 0x20 || code === 0x7f) return true;
  }
  return false;
}

/**
 * Google's sign-in leaves the page, so the router state that carried the
 * destination is gone when the callback loads. It rides in sessionStorage
 * across that one round trip, as the OAuth nonce does; it is not data.
 */
const KEY = 'lexpad.returnPath';

export function rememberReturnPath(raw: unknown): void {
  try {
    const path = safeReturnPath(raw);
    if (path === undefined) sessionStorage.removeItem(KEY);
    else sessionStorage.setItem(KEY, path);
  } catch {
    // Storage blocked: the callback falls back to Today.
  }
}

/** Reads and forgets the remembered destination; validated again on the way out. */
export function takeReturnPath(): string | undefined {
  try {
    const stored = sessionStorage.getItem(KEY);
    sessionStorage.removeItem(KEY);
    return safeReturnPath(stored);
  } catch {
    return undefined;
  }
}
