/**
 * Where Settings and its pages live. Settings is a short list of rows, each
 * opening one page, the way a phone's own settings work; every page is a
 * real address so the back button, Android's back key, an iPhone's swipe
 * and a link from a notification or an e-mail all land where they should.
 */
export const SETTINGS_ROOT = '/settings';

/** The pages under Settings, by the last part of their address. */
export const SETTINGS_PAGES = [
  'account',
  'notebooks',
  'practice',
  'notifications',
  'appearance',
  'connected-apps',
  'everywhere',
  'data',
  'plan',
  'about',
  // How words come back (SRS v2), for the notebook being shown. Reached from
  // Notebooks and Practice, never from the main list.
  'schedule',
  // Only inside the desktop app (Settings shows its row nowhere else).
  'desktop',
  // How Lexpad works (the new learner's journey), from Help & about, the
  // first session summaries and the schedule page. Its own chunk.
  'how',
] as const;

export type SettingsPageId = (typeof SETTINGS_PAGES)[number];

/** The address of one page under Settings. */
export function settingsPath(page: SettingsPageId): string {
  return `${SETTINGS_ROOT}/${page}`;
}

/**
 * Where another screen may open this page (SRS v2 access): Today's Smart
 * invitation opens it at the scheduler with Smart in focus (never switched),
 * and the daily-limit offer at the daily review limit.
 */
export const SCHEDULE_FOCUS = { smart: 'smart', limits: 'limits', hardWords: 'hard-words' } as const;

/** The cards of "How Lexpad works" another screen may open it at. */
export const HOW_FOCUS = { boxes: 'boxes' } as const;
