import { useEffect, useState } from 'react';
import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { Spinner } from '@/components/ui/Spinner.js';
import { useAuth } from '@/features/auth/session.js';
import { listNotebooks } from '@/db/repo.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { startSync } from '@/sync/store.js';
import { syncReminder } from '@/features/settings/reminders.js';
import { registerDevice, registerPushToken } from '@/features/auth/session.js';
import { platform } from '@/lib/platform/index.js';
import { introSeen } from '@/features/intro/seen.js';
import { clearIntroWord, peekIntroWord } from '@/features/intro/introWord.js';
import { safeReturnPath } from '@/features/auth/returnPath.js';
import { noteArrival } from '@/features/everywhere/state.js';
import { useBilling } from '@/features/billing/state.js';
import { forgetHeldTrialMoments } from '@/features/today/useTrial.js';

/**
 * Screens a signed-in account reaches before it has a notebook. Onboarding
 * creates the notebook, so sending it to itself would loop; the assistant
 * consent screen and the desktop app's and the extension's connect pages are
 * visits from a program that must finish where they started, or the program
 * waits for an answer that never comes (the extension 0.3.0 opens its page in
 * the browser's own window, which only closes at the answer; both say to make
 * a notebook after).
 */
const BEFORE_A_NOTEBOOK = new Set(['/welcome', '/connect/ai', '/connect-desktop', '/connect-extension']);

/**
 * Visits from a program waiting for an answer (the desktop app, the browser
 * extension, an assistant). A stranger arriving this way came to connect
 * something, not to be asked for a word, so sign-in comes first.
 */
const FROM_A_PROGRAM = new Set(['/connect/ai', '/connect-desktop', '/connect-extension']);

/** Undefined while the local database is still being asked. */
async function countNotebooks(): Promise<number> {
  return (await listNotebooks()).length;
}

/**
 * Decides what the user sees on launch: a spinner only while a stored
 * session is being checked, sign-in when there is none, and the app once
 * the local database is ready. Sync starts here, not in a screen, so it
 * runs for exactly as long as the user is signed in.
 */
export function AuthGate({ children }: { children: React.ReactNode }): React.JSX.Element {
  const status = useAuth((state) => state.status);
  const location = useLocation();
  const navigate = useNavigate();
  const notebooks = useLiveQuery(countNotebooks, -1, []);

  // A tapped notification opens the screen it is about. The host holds a tap
  // that launched the app until this listener exists, and one that arrives
  // signed out goes through sign-in like any other gated address.
  useEffect(
    () =>
      platform.push.onTap((path) => {
        void navigate(path);
      }),
    [navigate],
  );
  // The live count can lag a navigation by a tick: onboarding writes the
  // notebook and moves to Today before the subscription has re-read, and
  // the stale zero would send the learner straight back to the questions.
  // A zero is acted on only once a fresh read, made now for this very
  // location, agrees.
  const [emptyConfirmedAt, setEmptyConfirmedAt] = useState<string | null>(null);
  useEffect(() => {
    if (notebooks !== 0) return;
    let live = true;
    void countNotebooks().then((count) => {
      if (live && count === 0) setEmptyConfirmedAt(location.pathname);
    });
    return () => {
      live = false;
    };
  }, [notebooks, location.pathname]);
  const confirmedEmpty = notebooks === 0 && emptyConfirmedAt === location.pathname;

  // A visit that came from ChatGPT or Claude, remembered across the sign-up
  // it leads to: the connector card on Today waits for exactly that.
  useEffect(() => {
    if (status === 'signedOut') noteArrival(document.referrer);
  }, [status]);

  // The plan belongs to the account: a different one signed in in this tab
  // starts from nothing, and the plan is asked for as the app opens, so
  // Today usually has it before it draws (its trial card waits for it).
  const accountId = useAuth((state) => state.user?.id);
  useEffect(() => {
    if (status !== 'ready' || accountId === undefined) return;
    if (useBilling.getState().belongsTo(accountId)) forgetHeldTrialMoments();
    useBilling.getState().ensure();
  }, [status, accountId]);

  useEffect(() => {
    if (status !== 'ready') return;
    // The reminder may have been changed on another device; the host's
    // schedule follows the synced setting.
    void syncReminder().catch(() => undefined);
    // The account's device list learns about this install, or refreshes it,
    // with the push token when notifications are already allowed.
    void registerDevice();
    // Firebase rotates tokens; the server must follow or the phone goes quiet.
    const stopToken = platform.push.onToken((token) => {
      void registerPushToken(token);
    });
    const stopSync = startSync();
    return () => {
      stopToken();
      stopSync();
    };
  }, [status]);

  // Somebody who typed a word on the introduction and then signed in to an
  // account that already has notebooks never sees onboarding, which is where
  // the word would have gone. It is offered once instead: the add sheet,
  // with the word in it (the notebook takes it from there). Arriving
  // anywhere else, at a link they were following, lets it go.
  const settled = status === 'ready' && notebooks > 0;
  const handingOff = settled && location.pathname === '/' ? peekIntroWord() : undefined;
  const carried = (location.state as { introWord?: unknown } | null)?.introWord;
  useEffect(() => {
    if (!settled || location.pathname === '/') return;
    if (location.pathname === '/notebook' && carried !== undefined) return;
    clearIntroWord();
  }, [settled, location.pathname, carried]);
  if (handingOff !== undefined) {
    return <Navigate to="/notebook?add=1" replace state={{ introWord: handingOff }} />;
  }

  if (status === 'checking') return <Spinner />;
  if (status === 'signedOut') {
    // Remember where the user was heading, query string included, so a
    // mid-session expiry or an assistant's consent link returns them there
    // rather than to Today. A device that has never had a session sees the
    // introduction first, which carries the destination on to sign-in.
    const from = `${location.pathname}${location.search}`;
    if (!introSeen() && !FROM_A_PROGRAM.has(location.pathname)) {
      return <Navigate to="/intro" replace state={{ from }} />;
    }
    return <Navigate to="/auth" replace state={{ from }} />;
  }
  // A signed-in user with no notebook has not been set up yet, whether that
  // is a new account or a new device whose snapshot was empty. Onboarding
  // itself is outside this check, or it could never create the notebook.
  if (confirmedEmpty && !BEFORE_A_NOTEBOOK.has(location.pathname)) {
    return <Navigate to="/welcome" replace />;
  }
  return <>{children}</>;
}

/** Keeps a signed-in user away from the sign-in screen. */
export function SignedOutOnly({ children }: { children: React.ReactNode }): React.JSX.Element {
  const status = useAuth((state) => state.status);
  const location = useLocation();
  // The gate records where a signed-out user was heading; sign-in takes them
  // back there, but only to a path on this origin (never an open redirect).
  const from = safeReturnPath((location.state as { from?: unknown } | null)?.from);
  if (status === 'checking') return <Spinner />;
  if (status === 'ready') return <Navigate to={from ?? '/'} replace />;
  return <>{children}</>;
}
